INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhongshan','中山','["中山","中山国"]',NULL,'{"periods":[{"rank":"侯","start":{"year":-424,"month":1,"confidence":"year"},"end":{"year":-324,"month":12,"confidence":"year"}},{"rank":"王","start":{"year":-323,"month":1,"confidence":"year"},"end":{"year":-296,"month":12,"confidence":"month"}}]}','cn','east_asia',-424,1,NULL,'year',-296,12,NULL,'month',-5076,-3529,'ochre',NULL,NULL,'鲜虞白狄所建。有年表自文公、武公；前406年后亡国，桓公复兴。前296年赵灭中山。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhongshan-r0','','zhongshan','["中山文公"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','中山文公是战国中山国早期君主。其年代主要依后世年表推定；现存材料不足以确认其与后续君主之间的具体世系。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/中山文公"}]','文',NULL,'文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhongshan-r1','窟','zhongshan','["中山武公"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','中山武公名姬窟，承中山文公而立。中山国在其后逐步恢复并发展为战国北方强国之一；其具体政绩和准确在位年仍有年代异说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/中山武公"}]','武',NULL,'武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhongshan-r2','','zhongshan','["中山桓公"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','中山桓公，武公后即位，约前406年魏灭中山；约前380年复国，约前350年卒。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/中山桓公"}]','桓',NULL,'桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhongshan-r3','','zhongshan','["中山成公"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','中山成公在位年代约为前349至前328年。其后中山国进入厝执政时期，相关年表主要依据出土中山王器铭与后世编年互证。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/中山成公"}]','成',NULL,'成公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhongshan-r4','厝','zhongshan','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','中山王厝（器铭字形亦释作𰯼）在位时扩建灵寿、经营中山国都城，并留下重要青铜器铭文；其后赵国持续施压，中山国逐渐衰弱。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/中山王厝"},{"label":"河北省文物考古研究院：河北百年百项重要考古发现—中山王墓","url":"https://www.hbswwkg.com/2021-12/26/content_8697074.html"},{"label":"河北省民族事务委员会：战国第八雄·中山的华夏化与儒化","url":"https://mw.hebei.gov.cn/system/2023/08/18/030242432.shtml"},{"label":"《史记·赵世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷043"}]',NULL,NULL,'厝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhongshan-r5','𧊒','zhongshan','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','中山王𧊒，约前309–前299年在位；前299年赵破灵寿后逃齐卒。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/中山王𧊒"}]',NULL,NULL,'𧊒','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhongshan-r6','尚','zhongshan','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','中山王尚在位时赵国加强攻势，前296年中山国被赵灭亡；其统治是中山独立政权的最后阶段，姓名及事迹记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/中山王尚"}]',NULL,NULL,'尚','[]');
