INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('zhongshan-cuo-assumes-kingship','中山厝参与相王','politics','point','year',NULL,NULL,'采用前323年系年；五国相王的参与及赵是否实际称王应区分，不能将赵武灵王拒绝王号改写为同年正式称王。',-323,12,NULL,-3853,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-323年，中山君厝参与魏国公孙衍倡议的五国相王，通过与韩、赵、魏、燕等国结盟、互认王号，争取与大国对等的政治身份，并抗衡秦、齐、楚的影响。中山以较小国力进入称王诸国之列，王号体现外交承认与自身政治诉求；后来的中山王器铭也保存了其王号，不能把王称理解为周天子授爵。',NULL,NULL,'[{"label":"河北省民族事务委员会：战国第八雄·中山的华夏化与儒化","url":"https://mw.hebei.gov.cn/system/2023/08/18/030242432.shtml"},{"label":"《史记·赵世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷043"}]');
